private val mutationSeq = AtomicLong(0L)
private val latestPublishedMutation = AtomicLong(0L)
private val inFlightMutations = AtomicInteger(0)
private val requestSeq = AtomicLong(0L)
private val latestPublishedRequest = AtomicLong(0L)
private val cacheLock = Any()

