private val isAdminActionInProgress = java.util.concurrent.atomic.AtomicBoolean(false)

fun adminDeleteCampaign(reason: String? = null, onDeleted: () -> Unit) {
    if (!isAdminActionInProgress.compareAndSet(false, true)) return

    val initiatingUid = repository.currentUserId()
    val initiatingGen = SessionCacheManager.currentGeneration()
    if (initiatingUid == null) {
        isAdminActionInProgress.set(false)
        _uiState.update {
            it.copy(
                isActionLoading = false,
                error = localizer.get(R.string.error_permission_denied),
            )
        }
        return
    }

    _uiState.update { it.copy(isActionLoading = true, error = null) }
    refreshSequence.incrementAndGet()

    viewModelScope.launch {
        try {
            if (repository.currentUserId() != initiatingUid || SessionCacheManager.currentGeneration() != initiatingGen) {
                return@launch
            }

            repository.adminDeleteCampaign(campaignId, reason)

            if (repository.currentUserId() != initiatingUid || SessionCacheManager.currentGeneration() != initiatingGen) {
                return@launch
            }

            refreshSequence.incrementAndGet()
            _uiState.update {
                it.copy(
                    isActionLoading = false,
                    message = localizer.get(R.string.campaign_remove_success_msg),
                )
            }
            onDeleted()
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            if (repository.currentUserId() != initiatingUid || SessionCacheManager.currentGeneration() != initiatingGen) {
                return@launch
            }
            _uiState.update {
                it.copy(
                    isActionLoading = false,
                    error = localizer.get(R.string.campaign_remove_failed_format, friendlyError(e, localizer)),
                )
            }
        } finally {
            isAdminActionInProgress.set(false)
            if (repository.currentUserId() == initiatingUid && SessionCacheManager.currentGeneration() == initiatingGen) {
                if (_uiState.value.isActionLoading) {
                    _uiState.update { it.copy(isActionLoading = false) }
                }
            }
        }
    }
}

